/**
 * fast-provider.test.ts — the fast-completion ladder.
 *
 * The failure it guards (live 2026-11-06): the suggestion chips above the
 * prompt bar are regenerated by the AI after every message, but the lane
 * ONLY tried the first env fast key and returned null on ANY failure — all
 * three keys in the dev .env answered 401 while the user's in-app BYOK keys
 * kept the chat alive. Result: the AI chips never appeared and the static
 * utility chips showed forever. The ladder must move on: a dead first key
 * cannot kill the feature, and extras (the user's own lanes) trail in.
 */

import { fastCompletion, getFastProviders } from "../fast-provider";

const textBody = (content: string) =>
  new Response(
    JSON.stringify({ choices: [{ message: { content } }] }),
    { status: 200, headers: { "Content-Type": "application/json" } }
  );

describe("fastCommand ladder", () => {
  const originalFetch = global.fetch;

  afterEach(() => {
    global.fetch = originalFetch;
    delete process.env.GROQ_API_KEY;
    delete process.env.NVIDIA_API_KEY;
  });

  it("first dead key does not kill the call — the next provider answers", async () => {
    process.env.GROQ_API_KEY = "dead-key";
    process.env.NVIDIA_API_KEY = "live-key";
    const tried: string[] = [];
    global.fetch = (async (input: RequestInfo | URL) => {
      const url = String(input);
      tried.push(url);
      if (url.includes("api.groq.com")) {
        return new Response(JSON.stringify({ error: "Invalid API Key" }), { status: 401 });
      }
      return textBody("The answer from NVIDIA.");
    }) as typeof fetch;

    const out = await fastCompletion("system", [{ role: "user", content: "hi" }]);
    expect(out).toBe("The answer from NVIDIA.");
    // The ladder really moved past the dead first provider.
    expect(tried.some((u) => u.includes("api.groq.com"))).toBe(true);
    expect(tried.some((u) => u.includes("api.nvidia.com") || u.includes("integrate.api.nvidia.com"))).toBe(true);
  });

  it("a user's own lane (extras) answers when every env key is dead", async () => {
    process.env.GROQ_API_KEY = "dead-key";
    global.fetch = (async (input: RequestInfo | URL) => {
      const url = String(input);
      if (url.includes("api.groq.com")) {
        return new Response(JSON.stringify({ error: "Invalid API Key" }), { status: 401 });
      }
      return textBody("Suggested next steps.");
    }) as typeof fetch;

    const out = await fastCompletion(
      "system",
      [{ role: "user", content: "rate my project" }],
      undefined,
      [{ name: "minimax-personal", url: "https://byok.example/chat/completions", apiKey: "live-byok", model: "minimax/m3.1" }]
    );
    expect(out).toBe("Suggested next steps.");
  });

  it("all candidates dead → null (never throws)", async () => {
    process.env.GROQ_API_KEY = "dead-key";
    global.fetch = (async () =>
      new Response(JSON.stringify({ error: "nope" }), { status: 401 })) as typeof fetch;
    const out = await fastCompletion("system", [{ role: "user", content: "hi" }], undefined, [
      { name: "dead-byok", url: "https://x.example/chat/completions", apiKey: "k", model: "m" },
    ]);
    expect(out).toBeNull();
  });

  it("getFastProviders lists every CONFIGURED env provider in order", () => {
    process.env.GROQ_API_KEY = "g";
    process.env.NVIDIA_API_KEY = "n";
    const list = getFastProviders();
    expect(list.map((p) => p.name)).toEqual(["Groq-Fast", "NVIDIA-Fast"]);
  });
});
